arguments.command:
python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx')
ws = wb['Budget']
print('Dims:', ws.dimensions)
for row in ws.iter_rows():
    for cell in row:
        if cell.value is not None:
            print(f'{cell.coordinate}: value={cell.value!r} | font_color={cell.font.color.rgb if cell.font and cell.font.color else None} | bold={cell.font.bold if cell.font else None} | num_fmt={cell.number_format!r}')
"
